export interface TextCell {
  readonly text: string;
  readonly [key: string]: unknown;
}

export type CellTree = readonly (TextCell | CellTree)[];

/**
 * Validates an unknown root as an acyclic CellTree and returns its leaf text
 * values in left-to-right depth-first order.
 *
 * @param input - The value to validate. It must be an array containing only
 * nested arrays and non-null objects with an own string-valued `text` property.
 * @returns A new array containing the text from every leaf.
 * @throws TypeError if the root or any nested value is malformed, or if an
 * array cycle is encountered.
 */
export function flattenCellText(input: unknown): string[] {
  if (!Array.isArray(input)) {
    throw new TypeError("input must be an array");
  }

  const output: string[] = [];
  const active = new WeakSet<object>();

  const visit = (array: readonly unknown[]): void => {
    if (active.has(array)) {
      throw new TypeError("cyclic array");
    }

    active.add(array);
    for (const item of array) {
      if (Array.isArray(item)) {
        visit(item);
      } else if (
        typeof item === "object" &&
        item !== null &&
        Object.prototype.hasOwnProperty.call(item, "text") &&
        typeof (item as { text?: unknown }).text === "string"
      ) {
        output.push((item as TextCell).text);
      } else {
        throw new TypeError("invalid cell");
      }
    }
  };

  visit(input);
  return output;
}

