import { flattenCellText } from './solution';
import type { CellTree, TextCell } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function assertArray(actual: readonly string[], expected: readonly string[], message: string): void {
  assert(actual.length === expected.length, `${message}: wrong length`);
  for (let index = 0; index < expected.length; index += 1) {
    assert(actual[index] === expected[index], `${message}: mismatch at ${index}`);
  }
}

function assertThrowsTypeError(action: () => unknown, message: string): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof TypeError, `${message}: expected TypeError`);
    return;
  }
  throw new Error(`${message}: expected an exception`);
}

const first: TextCell = { text: 'first' };
const shared: CellTree = [{ text: 'shared' }, [{ text: 'deep', extra: true }]];
const tree: CellTree = [first, [], shared, { text: '' }, shared, { text: 'last' }];
const flattened = flattenCellText(tree);
assertArray(flattened, ['first', 'shared', 'deep', '', 'shared', 'deep', 'last'], 'depth-first traversal');
flattened[0] = 'changed result';
assert(first.text === 'first', 'result must not expose leaf objects');
assert((shared[0] as TextCell).text === 'shared', 'input must not be mutated');
assertArray(flattenCellText([]), [], 'empty root');

const frozenLeaf = Object.freeze({ text: 'frozen' });
const frozenTree = Object.freeze([Object.freeze([frozenLeaf])]);
assertArray(flattenCellText(frozenTree), ['frozen'], 'frozen input');

const inherited = Object.create({ text: 'inherited' }) as object;
assertThrowsTypeError(() => flattenCellText([inherited]), 'inherited text is not own');
for (const invalid of [
  null,
  { text: 'root leaf' },
  [null],
  [3],
  ['text'],
  [{}],
  [{ text: 4 }],
  [[{ text: 'valid' }], undefined],
]) {
  assertThrowsTypeError(() => flattenCellText(invalid), 'malformed tree');
}

const directCycle: unknown[] = [];
directCycle.push(directCycle);
assertThrowsTypeError(() => flattenCellText(directCycle), 'direct cycle');

const left: unknown[] = [];
const right: unknown[] = [left];
left.push({ text: 'before-cycle' }, right);
assertThrowsTypeError(() => flattenCellText(left), 'indirect cycle');

